import React from 'react';

function Header() {
  return (
    <header className="header">
      <div className="header-content">
        <h1>✨ AI <span>Product Description</span> Generator</h1>
        <span className="header-badge">⚡ Powered by AI</span>
      </div>
    </header>
  );
}

export default Header;
